// Code generated from U_09A0.C (PASSAGE_show) by hand-run script; the passage texts and layouts.

package intro

var passages = map[int]passage{
	0: {Block: 1, BlockX: 1, BlockY: 159, TextX: 8, TextY: 169, TextRight: 304, TextBottom: 15, Centered: true,
		Text: "Upon your world, five seasons have passed since your " +
			"triumphant homecoming from Britannia."},
	1: {Block: 2, BlockX: 1, BlockY: 152, TextX: 8, TextY: 160, TextRight: 303, TextBottom: 31, Centered: false,
		Text: "You have traded the Avatar's life of peril and adventure " +
			"for the lonely serenity of a world at peace. But " +
			"television supermen cannot take the place of friends " +
			"who died at your side!"},
	2: {Block: 0, BlockX: 33, BlockY: 157, TextX: 40, TextY: 165, TextRight: 234, TextBottom: 7, Centered: true,
		Text: "Outside, a chill wind rises..."},
	3: {Block: 1, BlockX: 0, BlockY: 152, TextX: 8, TextY: 166, TextRight: 303, TextBottom: 15, Centered: true,
		Text: "...and in moments, the storm is upon you."},
	4: {Block: 1, BlockX: 1, BlockY: 152, TextX: 8, TextY: 162, TextRight: 303, TextBottom: 15, Centered: false,
		Text: "Tongues of lightning lash the sky, conducting an unceasing " +
			"crescendo of thunder...."},
	5: {Block: 1, BlockX: 1, BlockY: 152, TextX: 8, TextY: 162, TextRight: 303, TextBottom: 15, Centered: false,
		Text: "In a cataclysm of sound and light, a bolt of searing " +
			"blue fire strikes the earth!"},
	6: {Block: 1, BlockX: 1, BlockY: 152, TextX: 8, TextY: 162, TextRight: 303, TextBottom: 15, Centered: true,
		Text: "Lightning among the stones!\nIs this a sign from " +
			"distant Britannia?"},
	8: {Block: 2, BlockX: 1, BlockY: 152, TextX: 8, TextY: 164, TextRight: 303, TextBottom: 23, Centered: false,
		Text: "You bolt from your house, stumbling, running blind in the" +
			" storm. Into the forest, down the path, through the " +
			"rain... to the stones."},
	9: {Block: 2, BlockX: 1, BlockY: 12, TextX: 8, TextY: 20, TextRight: 303, TextBottom: 31, Centered: false,
		Text: "Near the stones, the smell of damp, blasted earth hangs " +
			"in the air. In a frozen moment of lightning-" +
			"struck daylight, you glimpse a tiny obsidian stone in the " +
			"midst of the circle!"},
	10: {Block: 0, BlockX: 33, BlockY: 30, TextX: 40, TextY: 38, TextRight: 234, TextBottom: 7, Centered: true,
		Text: "Wondering, you pick it up...."},
	11: {Block: 1, BlockX: 1, BlockY: 160, TextX: 8, TextY: 170, TextRight: 303, TextBottom: 15, Centered: false,
		Text: "...and from the heart of the stones, a softly glowing door " +
			"ascends in silence!"},
	12: {Block: 2, BlockX: 1, BlockY: 152, TextX: 8, TextY: 160, TextRight: 303, TextBottom: 31, Centered: false,
		Text: "Exultant memories wash over you as you clutch the stone. " +
			"When last you saw an orb such as this, it was cast down " +
			"by Lord British to banish the tyrant Blackthorn!"},
	13: {Block: 2, BlockX: 1, BlockY: 152, TextX: 8, TextY: 160, TextRight: 303, TextBottom: 31, Centered: true,
		Text: "But your joy soon gives way to apprehension.\n\n" +
			"The gate to Britannia has always been blue...\nas " +
			"blue as the morning sky."},
	14: {Block: 1, BlockX: 1, BlockY: 160, TextX: 8, TextY: 170, TextRight: 303, TextBottom: 15, Centered: false,
		Text: "Abruptly, the portal quivers and begins to sink " +
			"into the ground.  Its crimson light wanes!"},
	15: {Block: 1, BlockX: 1, BlockY: 160, TextX: 8, TextY: 174, TextRight: 303, TextBottom: 15, Centered: true,
		Text: "Desperation makes the decision an easy one."},
	100: {Block: 1, BlockX: 1, BlockY: 160, TextX: 8, TextY: 174, TextRight: 303, TextBottom: 15, Centered: true,
		Text: "\"Welcome, O Seeker!" + closeQuote},
	101: {Block: 2, BlockX: 1, BlockY: 152, TextX: 8, TextY: 164, TextRight: 303, TextBottom: 23, Centered: false,
		Text: "A lonely stroll along an unfamiliar forest path brings you " +
			"upon a curious gypsy wagon, its exotic colors dappled in the " +
			"summer shade."},
	102: {Block: 2, BlockX: 1, BlockY: 152, TextX: 8, TextY: 164, TextRight: 303, TextBottom: 23, Centered: false,
		Text: "A woman's voice rings out with friendship, beckoning you into " +
			"across the wagon's threshold and, as it happens, " +
			"into another life...."},
	103: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 143, TextRight: 303, TextBottom: 39, Centered: false,
		Text: "\"At last thou hast come to fulfill thy destiny," + closeQuote + " " +
			"the gypsy says. She smiles, as if in great relief.\n\n" +
			"\"Sit before me now, and I shall pour the light of Virtue " +
			"into the shadows of thy future." + closeQuote},
	104: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 143, TextRight: 303, TextBottom: 39, Centered: false,
		Text: "On a wooden table eight bottles stand, a rainbow of bubbling " +
			"liquids.\n\n" +
			"\"Behold the Virtues of the Avatar," + closeQuote + " the woman " +
			"says. \"Let us begin the casting!" + closeQuote},
	105: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"Entrusted to deliver an uncounted purse of gold, thou dost " +
			"meet a poor beggar. Dost thou A) deliver the gold Honestly, " +
			"knowing the trust in thee was well-placed; or B) show Compassion and " +
			"give the beggar a coin, knowing it won't be missed?" + closeQuote},
	106: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"Thou has been prohibited by thy absent Lord from joining " +
			"thy friends in a close-pitched battle. Dost thou A) refrain, " +
			"so thou may Honestly claim obedience; or B) show Valor and aid " +
			"thy comrades, knowing thou may deny it later?" + closeQuote},
	107: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"A merchant owes thy friend money, now long past due. Thou " +
			"dost see the same merchant drop a purse of gold. Dost thou " +
			"A) Honestly return the purse intact; or B) Justly give thy " +
			"friend a portion of the gold first?" + closeQuote},
	108: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"Thee and thy friend are valiant but penniless warriors. Thou " +
			"both set forth to slay a mighty dragon. Thy friend dost " +
			"think he slew it, but the killing blow was thine. Dost thou " +
			"A) Honestly claim the reward; or B) Sacrifice the gold for the " +
			"sake of thy friendship?" + closeQuote},
	109: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"Thou art sworn to protect thy Lord at any cost, yet thou knowest " +
			"he hath committed a crime. Authorities ask thee of the affair. " +
			"Dost thou A) Break thine oath by Honestly speaking; or B) uphold " +
			"Honor by silently keeping thine oath?" + closeQuote},
	110: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"Thy friend doth seek admittance to thy spiritual order. Thou " +
			"art asked to vouch for his purity of spirit, of which thou art " +
			"uncertain. Dost thou A) Honestly express thy doubt; or B) Vouch " +
			"for him, hoping for his Spiritual improvement?" + closeQuote},
	111: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"Thy Lord doth mistakenly believe he slew a dragon. Thou hast " +
			"proof that thy lance felled the beast. When asked, dost thou " +
			"A) Honestly claim the kill; or B) Humbly permit thy Lord his " +
			"belief?" + closeQuote},
	112: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"Thou dost manage to disarm thy mortal enemy in a duel. He is " +
			"at thy mercy. Dost thou A) Show Compassion by permitting him to " +
			"yield; or B) Slay him, as expected of a Valiant duelist?" + closeQuote},
	113: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"After twenty years thou hast found the slayer of thy best " +
			"friends. The villain proves to be a man who provides the sole " +
			"support for a young girl. Dost thou A) Spare him in Compassion " +
			"for the child; or B) Slay him in the name of Justice?" + closeQuote},
	114: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"Thee and thy friends hath been routed and ordered to retreat. " +
			"In defiance of thy orders, dost thou A) Stop in Compassion to aid " +
			"a wounded comrade; or B) Sacrifice thyself to slow the pursuing " +
			"enemy so that others might escape?" + closeQuote},
	115: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"Thou art sworn to uphold a Lord who doth participate in the " +
			"forbidden torture of prisoners. Each night their cries of pain " +
			"reach thee. Dost thou A) Show Compassion by reporting the deeds; " +
			"or B) Honor thy oath and ignore the deeds?" + closeQuote},
	116: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"Thou hast been taught to preserve all life as sacred. A man " +
			"lies fatally stung by a venomous serpent. He prays for a " +
			"merciful death. Dost thou A) Show Compassion and end his pain; " +
			"or B) heed thy Spiritual beliefs and turn away?" + closeQuote},
	117: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"The Captain of the King's Guard asks that one among thee " +
			"visit a hospital to cheer the children with tales of valiant personal " +
			"deeds. Dost thou A) Show thy Compassion and play the braggart; " +
			"or B) Humbly let another go?" + closeQuote},
	118: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"Thou hast been sent to secure a needed treaty with a distant " +
			"Lord. Thy host is agreeable to thy proposal but insults thy " +
			"country at dinner. Dost thou A) Valiantly bear the slurs; or " +
			"B) Justly rise and demand an apology?" + closeQuote},
	119: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"A burly knight accosts thee and demands thy food. Dost thou " +
			"A) Valiantly refuse and engage the knight, or B) Sacrifice " +
			"thy rations unto the hungry knight?" + closeQuote},
	120: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"During battle thou art ordered to guard thy commander's empty " +
			"tent. The battle goes poorly and thou dost yearn to aid thy " +
			"fellows. Dost thou A) Valiantly enter the battle; " +
			"or B) Honor thy post as guard?" + closeQuote},
	121: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"A local bully pushes for a fight. Dost thou A) Valiantly " +
			"trounce the rogue; or B) Decline, knowing in thy Spirit that " +
			"no lasting good will come of it?" + closeQuote},
	122: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"Although a simple fisherman, thou art also a skillful swordsman. Thy " +
			"Lord dost seek to assemble a peacetime guard. Dost thou A) Answer " +
			"the call, so that all may witness thy Valor; or B) Humbly decline the " +
			"offer to join thy Lord's largely ceremonial knighthood?" + closeQuote},
	123: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"During a pitched battle, thou dost see a fellow desert his " +
			"post, endangering many. As he flees, he is set upon by several enemies." +
			" Dost thou A) Justly let him fight alone; or B) Risk the Sacrifice " +
			"of thine own life to aid him?" + closeQuote},
	124: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"Thou hast sworn to do thy Lord's bidding in all. He covets " +
			"a piece of land and orders its owner removed. Dost thou A) Serve " +
			"Justice, refusing to act, thus being disgraced; or B) Honor thine " +
			"oath and evict the landowner?" + closeQuote},
	125: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"Thou dost believe that virtue resides in all people. Thou dost see " +
			"a rogue steal from thy Lord. Dost thou A) Call him to Justice; or B) " +
			"Personally try to sway him back to the Spiritual path of good?" + closeQuote},
	126: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"Unwitnessed, thou hast slain a mighty dragon in defense " +
			"of thy life. A poor warrior claims the offered reward. " +
			"Dost thou A) Justly step forward to claim the bounty; " +
			"or B) Humbly go about thy life, secure in thy self-esteem?" + closeQuote},
	127: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"Thou art a bounty hunter sworn to return an alleged murderer. " +
			"After his capture, thou dost come to believe him innocent. Dost " +
			"thou A) Sacrifice thy sizable bounty for thy belief; or B) Honor " +
			"thine oath to return him as promised?" + closeQuote},
	128: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"Thou hast spent thy life in charitable and righteous work. Thine " +
			"uncle the innkeeper lies ill and asks thee to take over his tavern. " +
			"Dost thou A) Sacrifice thy life of purity to aid thy kin; or B) " +
			"Decline and follow the call of Spirituality?" + closeQuote},
	129: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"Thou art an elderly, wealthy merchant. Thy end is near. Dost thou " +
			"A) Sacrifice all thy wealth to feed hundreds of starving children, " +
			"receiving public adulation; or B) Humbly live out thy life, willing " +
			"thy fortune to thy heirs?" + closeQuote},
	130: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"In thy youth thou didst pledge to marry thy sweetheart. Now " +
			"thou art on a sacred quest in distant lands. Thy sweetheart " +
			"doth ask thee to keep thy vow. Dost thou A) Honor thy pledge to " +
			"wed; or B) Follow thy Spiritual crusade?" + closeQuote},
	131: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"Though thou art but a peasant shepherd, thou art discovered to be the " +
			"sole descendant of a noble family long thought extinct. " +
			"Dost thou A) Honorably take up the arms of thy ancestors; or " +
			"B) Humbly resume thy life of simplicity and peace?" + closeQuote},
	132: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 133, TextRight: 303, TextBottom: 55, Centered: false,
		Text: "\"Thy parents wish thee to become an apprentice. Two positions " +
			"are available. Dost thou A) Become an acolyte in a worthy Spiritual " +
			"order; or B) Become an assistant to a humble village cobbler?" + closeQuote},
	133: {Block: 3, BlockX: 1, BlockY: 124, TextX: 8, TextY: 140, TextRight: 303, TextBottom: 47, Centered: false,
		Text: "\"The path of the Avatar lies beneath thy feet, worthy " + nameMarker + "," + closeQuote + " " +
			"the gypsy intones. With a mysterious smile, she passes you the flask of shimmering liquids. " +
			"\"Drink of these waters and go forth among our people, who " +
			"shall receive thee in joy!" + closeQuote},
	134: {Block: 2, BlockX: 1, BlockY: 152, TextX: 8, TextY: 160, TextRight: 303, TextBottom: 31, Centered: false,
		Text: "As you drink from the flask, vertigo overwhelms you. " +
			"A soothing mist obscures the gypsy's face, and you sink " +
			"without fear into an untroubled sleep."},
	135: {Block: 2, BlockX: 1, BlockY: 152, TextX: 8, TextY: 160, TextRight: 303, TextBottom: 31, Centered: false,
		Text: "You wake in a different time, upon another world's shore. " +
			"Though the Avatar's quests bring you both triumph and tragedy, " +
			"never do you stray from the path of the Eight Virtues."},
	136: {Block: 2, BlockX: 1, BlockY: 152, TextX: 8, TextY: 160, TextRight: 303, TextBottom: 31, Centered: false,
		Text: "The sagas of Ultima IV and Ultima V chronicle your perilous " +
			"travels, and your name and your deeds are written forever among " +
			"Britannia's legends...."},
	137: {Block: 2, BlockX: 1, BlockY: 152, TextX: 8, TextY: 164, TextRight: 303, TextBottom: 23, Centered: false,
		Text: "Finally, tempered by your struggles against the enemies of Virtue, you " +
			"are proven ready to answer the epic challenge of Ultima VI!"},
	200: {Block: 2, BlockX: 1, BlockY: 152, TextX: 8, TextY: 160, TextRight: 303, TextBottom: 31, Centered: false,
		Text: "Dazed, you emerge from the portal to find yourself " +
			"standing on a desolate plain. Nearby rests a massive " +
			"rune-struck altar, shrouded in moonlit fog."},
	201: {Block: 2, BlockX: 1, BlockY: 152, TextX: 8, TextY: 160, TextRight: 303, TextBottom: 31, Centered: false,
		Text: "At first the plain is still. Then a hundred voices " +
			"raise a slow, deathlike song, drawing closer and " +
			"closer with each passing moment. You are seized " +
			"by an urge to run..."},
	202: {Block: 0, BlockX: 33, BlockY: 157, TextX: 40, TextY: 165, TextRight: 234, TextBottom: 7, Centered: true,
		Text: "...but you have no place to go."},
	203: {Block: 2, BlockX: 1, BlockY: 152, TextX: 8, TextY: 164, TextRight: 303, TextBottom: 23, Centered: false,
		Text: "Before you can offer a protest to the creatures " +
			"who surround you, scaly claws grasp your body."},
	204: {Block: 1, BlockX: 1, BlockY: 160, TextX: 8, TextY: 170, TextRight: 303, TextBottom: 15, Centered: true,
		Text: "With unearthly strength, the monsters bind you to the altar stone!"},
	205: {Block: 1, BlockX: 1, BlockY: 160, TextX: 8, TextY: 170, TextRight: 303, TextBottom: 15, Centered: true,
		Text: "Kneeling, the hordes sway and chant as a stately " +
			"winged nightmare steps forward."},
	206: {Block: 2, BlockX: 1, BlockY: 152, TextX: 8, TextY: 164, TextRight: 303, TextBottom: 23, Centered: false,
		Text: "The leader unwraps a velvet covered, brass-bound " +
			"book and recites from it in a formal, stilted tongue."},
	207: {Block: 2, BlockX: 1, BlockY: 152, TextX: 8, TextY: 164, TextRight: 303, TextBottom: 23, Centered: false,
		Text: "Shouts and jeers explode from the masses as the priest " +
			"slams shut the book. In his hand a malignant dagger " +
			"drips with moonlight."},
	208: {Block: 1, BlockX: 1, BlockY: 160, TextX: 8, TextY: 170, TextRight: 303, TextBottom: 15, Centered: true,
		Text: "You close your eyes. A dying scream, certainly your own, " +
			"curdles the air."},
	209: {Block: 1, BlockX: 1, BlockY: 80, TextX: 8, TextY: 94, TextRight: 303, TextBottom: 7, Centered: true,
		Text: "Catcalls, the dagger, a scream, Death...."},
	210: {Block: 1, BlockX: 1, BlockY: 80, TextX: 8, TextY: 94, TextRight: 303, TextBottom: 7, Centered: true,
		Text: "Pandemonium. Shrieks of rage, of terror."},
	211: {Block: 1, BlockX: 1, BlockY: 80, TextX: 8, TextY: 94, TextRight: 303, TextBottom: 7, Centered: true,
		Text: "From the inevitable, an impossibility emerges."},
	212: {Block: 1, BlockX: 1, BlockY: 80, TextX: 8, TextY: 94, TextRight: 303, TextBottom: 7, Centered: true,
		Text: "You are still alive."},
	213: {Block: 2, BlockX: 1, BlockY: 152, TextX: 8, TextY: 160, TextRight: 303, TextBottom: 31, Centered: false,
		Text: "Silent red light fills the darkness. There is the wooden " +
			"clack of a crossbow, and a violet- fletched rose blooms " +
			"in the priest's barren forehead."},
	214: {Block: 2, BlockX: 1, BlockY: 152, TextX: 8, TextY: 160, TextRight: 303, TextBottom: 31, Centered: false,
		Text: "Friendly faces vault from a newborn moongate, while a " +
			"rain of quarrels holds the furious mob at bay. The " +
			"knight Dupre's sword flashes twice in the " +
			"darkness, slicing away your bonds!"},
	215: {Block: 2, BlockX: 1, BlockY: 152, TextX: 8, TextY: 160, TextRight: 303, TextBottom: 31, Centered: false,
		Text: "\"Quickly, old friend! To the gate!" + closeQuote + " Accompanied by the " +
			"swordsman Shamino and a grinning, crossbow-wielding " +
			"Iolo the Bard, Dupre thrusts a spare sword into your " +
			"hand."},
	216: {Block: 2, BlockX: 1, BlockY: 152, TextX: 8, TextY: 160, TextRight: 303, TextBottom: 31, Centered: false,
		Text: "Snatching the fallen priest's book, Iolo dives " +
			"into the redness with Shamino at his heels. The howling throng " +
			"surges forward, all of one terrible mind."},
	217: {Block: 1, BlockX: 1, BlockY: 160, TextX: 8, TextY: 170, TextRight: 303, TextBottom: 15, Centered: true,
		Text: "The gate wanes rapidly as you and Dupre charge through..."},
	218: {Block: 0, BlockX: 33, BlockY: 157, TextX: 41, TextY: 165, TextRight: 234, TextBottom: 7, Centered: true,
		Text: "...but not rapidly enough."},
	219: {Block: 2, BlockX: 1, BlockY: 152, TextX: 8, TextY: 160, TextRight: 303, TextBottom: 31, Centered: false,
		Text: "From the mob's vanguard, three of the abominations " +
			"scramble toward the gate. Driven by fury, " +
			"the creatures hurl their bodies into the " +
			"portal's last handspan of light!"},
}

